template <typename T = int, typename Comparator = std::less<T>> 
bool compare(const T& a, const T& b, Comparator comp = Comparator()){
  return comp(a, b);
}

//Example usage with default arguments:
compare(5, 10); // T deduced as int, Comparator as less<int>

// Example usage with custom comparator and explicit types:
struct Sales_data{};
bool compareIsbn(const Sales_data& a, const Sales_data& b){/*Compare logic*/ return true;}
compare(Sales_data(), Sales_data(), compareIsbn); // T deduced as Sales_data, Comparator as compareIsbn

