#include <iostream>
#include <functional>
template <typename T = int, typename Comparator = std::less<T>>
bool compare(const T& a, const T& b, Comparator comp = Comparator()){
  return comp(a, b);
}
struct Sales_data{};
bool compareIsbn(const Sales_data& a, const Sales_data& b){ return true; }
int main() {
  std::cout << compare(5, 10) << std::endl; // Uses default int and less<int>
  Sales_data sd1, sd2;
  std::cout << compare(sd1, sd2, compareIsbn) << std::endl; // Uses custom comparator
